command:
// ==========================================
// LUNAS WIRKUNG: FUNKENFELL (RONDRA)
//
// - Ziel: sich selbst
// - Dauer: QS × 2 Kampfrunden
// - Effektanlage über Block 5
// - Wirkungsende über Block 6
// - Trefferwächter über Block 18
// - fester Vergeltungsschaden in Höhe der QS
// - jeder erfolgreiche Treffer löst Vergeltung aus
// - Funkenfell bleibt nach Vergeltung aktiv
// - parallele Reaktion mit anderen Gaben
// - eine Karte + roter GM-Button über Block 19.8
// ==========================================

(async function () {
const macroUuid = this?.uuid || null;

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt = !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.Schaden?.GMKarte || !globalThis.DSK?.Schaden?.IstAktiverGM || !globalThis.DSK?.Schaden?.FindeActor || !globalThis.DSK?.Schaden?.Angriffswaechter?.Register || !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden || !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen || !globalThis.DSK?.GabenUI?.GMMakroButton || !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen || !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute(); await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (!DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register || !DSK_FW?.Schaden?.GMKarte || !DSK_FW?.Schaden?.IstAktiverGM || !DSK_FW?.Schaden?.FindeActor || !DSK_FW?.Schaden?.Angriffswaechter?.Register || !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde || !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden || !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen || !DSK_FW?.GabenUI?.GMMakroButton || !DSK_FW?.GabenUI?.AnfrageKarteErstellen || !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework inklusive Block 18 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

const gabenName = "Funkenfell", vollerName = "Funkenfell (Rondra)", ahne = "Rondra";
const reaktionsKey = "funkenfellRondra", flagKey = "pendingFunkenfellRondra";
const endeText = "Die schützende und vergeltende Aura des Funkenfells erlischt.";
DSK_FW.EffektEnde.Register(reaktionsKey, vollerName, endeText);

// +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const findeAlteEffekte = (actor, casterUuid) => (actor?.effects || []).filter(effect =>
    (effect.name || effect.label || "") === vollerName &&
    effect.getFlag("dsk", "isFunkenfell") === true &&
    effect.getFlag("dsk", "casterUuid") === casterUuid &&
    effect.getFlag("dsk", "schadensReaktion") === reaktionsKey
);

const beschreibungFuer = (casterName, qs) =>
    `<b>${casterName}</b> ist von einer schützenden und vergeltenden Aura umgeben.` +
    `<br><br>Wird der Effektträger erfolgreich getroffen, schlägt das Funkenfell gegen den Angreifer zurück. ` +
    `Der Angreifer erleidet <b>${qs} TP</b> Vergeltungsschaden.` +
    `<br><br><b>Zielkategorie:</b> Sich selbst`;

// +++ 4 - REAKTIONSWÄCHTER ÜBER BLOCK 18 ++++++++++++++++++

const registriereReaktion = ({ actor, effect }) => {
    if (!actor || !effect) return null;

    return DSK_FW.Schaden.Angriffswaechter.Register({
        key: `${reaktionsKey}-${actor.uuid}`, actor,
        effektId: effect.id, effektUuid: effect.uuid,
        rolle: "verteidiger", einmalig: false, protokollieren: true,

        beiErfolg: async ({ actor, effekt, message, angriff }) => {
            if (!DSK_FW.Schaden.IstAktiverGM() || !actor || !effekt || !message || !angriff || angriff.schaden <= 0) return false;

            const zielDaten = DSK_FW.Schaden.FindeActor(angriff.angreiferName, actor.id);
            if (!zielDaten?.actor) {
                ui.notifications.warn(`Luna sagt 🌙: Der Angreifer „${angriff.angreiferName}“ konnte nicht automatisch erkannt werden.`);
                return false;
            }

            const zielActor = zielDaten.actor;
            if (zielActor.id === actor.id || zielActor.uuid === actor.uuid) return false;

            const zielName = zielDaten.token?.name || zielDaten.name || DSK_FW.ResolveTokenName(zielActor);
            const effekttraegerName = DSK_FW.ResolveTokenName(actor);
            const basisTP = Math.max(1, Math.floor(Number(effekt.getFlag("dsk", "vergeltungsSchaden")) || 1));

            const schadensKarte = await DSK_FW.Schaden.GMKarte({
                key: `${reaktionsKey}-${effekt.id}-${message.id}`,
                titel: "Funkenfell – Vergeltung", ahne,
                zusammenfassung: `Angreifer erkannt: ${zielName}`,
                beschreibung:
                    `<b>${zielName}</b> gewinnt gegen <b>${effekttraegerName}</b>. ` +
                    `Das Funkenfell schlägt gegen den Angreifer zurück.` +
                    `<br><br>Der Angreifer erleidet <b>${basisTP} TP</b> Vergeltungsschaden.`,
                modus: "fest", basis: basisTP,
                ziele: [{ uuid: zielActor.uuid, name: zielName }],
                buttonText: `${basisTP} TP anwenden`,
                bestaetigungsTitel: "Funkenfell – Schaden angewendet",
                quelleUuid: actor.uuid, effektUuid: effekt.uuid,
                effektVerbrauchen: false, lepDetailsVerbergen: true
            });

            return Boolean(schadensKarte);
        }
    });
};

// +++ 5 - FUNKENFELL AUF GM-CLIENT ANLEGEN ++++++++++++++++

const wendeFunkenfellAn = async ({ casterActor, casterName, qs }) => {
    if (!casterActor || !DSK_FW.Schaden.IstAktiverGM()) return false;

    const dauerRunden = qs * 2, dauerText = `${dauerRunden} Kampfrunde(n) (${qs} QS × 2 KR)`;
    const beschreibung = beschreibungFuer(casterName, qs);
    const alteEffekte = findeAlteEffekte(casterActor, casterActor.uuid);

    if (alteEffekte.length) {
        await casterActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(effect => effect.id));
    }

    let erzeugterEffekt = null;

    try {
        erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName, ahne,
            beschreibung: `${beschreibung}<br><br><b>Wirkungsdauer:</b> ${dauerText}`,
            gabeZiel: "", qs, ziel: casterActor,
            duration: { rounds: dauerRunden, startTime: game.time.worldTime },
            showIcon: 1,
            flags: { dsk: {
                isFunkenfell: true, casterUuid: casterActor.uuid, casterName, qs,
                vergeltungsSchaden: qs, schadensReaktion: reaktionsKey,
                modus: "fest", rolle: "verteidiger", einmalig: false,
                wirkungsende: {
                    sfName: reaktionsKey, basisEffektName: vollerName,
                    beschreibungFuerEnde: endeText
                }
            }}
        });

        if (!erzeugterEffekt) throw new Error("Block 5 hat keinen Funkenfell-Effekt zurückgegeben.");

        const endeDaten = erzeugterEffekt.getFlag("dsk", "wirkungsende");
        const effektErfolgreich =
            (erzeugterEffekt.name || erzeugterEffekt.label || "") === vollerName &&
            erzeugterEffekt.getFlag("dsk", "isFunkenfell") === true &&
            erzeugterEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            erzeugterEffekt.getFlag("dsk", "casterName") === casterName &&
            Number(erzeugterEffekt.getFlag("dsk", "qs")) === qs &&
            Number(erzeugterEffekt.getFlag("dsk", "vergeltungsSchaden")) === qs &&
            erzeugterEffekt.getFlag("dsk", "schadensReaktion") === reaktionsKey &&
            erzeugterEffekt.getFlag("dsk", "modus") === "fest" &&
            erzeugterEffekt.getFlag("dsk", "rolle") === "verteidiger" &&
            erzeugterEffekt.getFlag("dsk", "einmalig") === false &&
            endeDaten?.sfName === reaktionsKey &&
            endeDaten?.basisEffektName === vollerName &&
            endeDaten?.beschreibungFuerEnde === endeText;

        if (!effektErfolgreich) throw new Error("Der Funkenfell-Effekt wurde nicht vollständig angelegt.");

        const waechterKey = registriereReaktion({ actor: casterActor, effect: erzeugterEffekt });
        if (!waechterKey) throw new Error("Der Funkenfell-Wächter konnte nicht registriert werden.");

        return true;
    } catch (error) {
        console.error("Funkenfell: Effektanlage/Wächterregistrierung fehlgeschlagen.", {
            casterActor: casterActor.name, casterUuid: casterActor.uuid, qs, error
        });

        if (erzeugterEffekt) await erzeugterEffekt.delete();
        return false;
    }
};

// +++ 6 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!casterActor || !daten || !DSK_FW.Schaden.IstAktiverGM()) return false;

    if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
        ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden.");
        return false;
    }

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);
    if (!casterToken) {
        ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
        return false;
    }

    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const erfolgreich = await wendeFunkenfellAn({ casterActor, casterName, qs });

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId, gabenName: vollerName, ahne,
        beschreibung: daten.beschreibung || "", wirkender: casterName,
        ziele: erfolgreich ? [{ name: casterName, rolle: "Aura aktiv" }] : [],
        misserfolge: erfolgreich ? [] : [{
            name: casterName,
            grund: "Effekt oder Schadensreaktion konnte nicht vollständig angelegt werden"
        }],
        dauerText: `${qs * 2} Kampfrunde(n) (${qs} QS × 2 KR)`,
        erfolgreich
    });

    if (erfolgreich) ui.notifications.info(`Luna sagt 🌙: Funkenfell ist auf ${casterName} aktiv.`);
    else ui.notifications.error("Luna sagt 🌙: Funkenfell konnte nicht vollständig aktiviert werden!");

    return true;
};

// +++ 7 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const anfrageActor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
            if (!daten) continue;

            if (await verarbeiteAnfrage(anfrageActor, daten)) {
                await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
            }
        }

        return;
    }
}

// +++ 8 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) ||
        null;
}

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
if (!game.user.isGM && !casterActor.isOwner) return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");

const casterName = DSK_FW.ResolveTokenName(casterActor);
const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor, gabenName,
    suchbegriffe: ["Funkenfell Probe", "Funkenfell"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0, protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Die schützende und vergeltende Aura konnte nicht entfacht werden.",
        wirkender: casterName, ziele: [],
        misserfolge: [{ name: casterName, grund: "Probe fehlgeschlagen" }],
        dauerText: "0 Kampfrunden", gmBereich: false,
        angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 9 - GEMEINSAME KARTE + GM-ANFRAGE +++++++++++++++++++

const dauerText = `${qs * 2} Kampfrunde(n) (${qs} QS × 2 KR)`;
const beschreibung = beschreibungFuer(casterName, qs);
const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid, "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung, wirkender: casterName,
    ziele: [{ name: casterName, rolle: "Aura aktivieren" }],
    misserfolge: [], dauerText,
    gmLink, gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
}

const anfrageDaten = {
    casterUuid: casterActor.uuid, casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
    qs, beschreibung,
    sceneId: canvas.scene?.id || null,
    requestedByUserId: game.user.id,
    messageId: nachricht.id,
    macroUuid, erstellt: Date.now()
};

if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, anfrageDaten);
    await raeumeQSAuf(casterActor);
    return;
}

await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);
await raeumeQSAuf(casterActor);
ui.notifications.info("Luna sagt 🌙: Funkenfell wurde bei der Spielleitung zur Aktivierung beantragt.");

}).call(this);
